def test_find_accumulate():
    import more_itertools.more as m
    import inspect
    src = inspect.getsource(m)
    lines = []
    for line_no, line in enumerate(src.splitlines(), 1):
        if 'accumulate' in line:
            lines.append((line_no, line))
    assert lines == [(1307, "    This is the inverse of :func:`itertools.accumulate`. By default")]

import more_itertools.more as m
import more_itertools.recipes as r
import more_itertools as mi

def test_all_symbols():
    for name in m.__all__:
        assert hasattr(m, name)
        assert hasattr(mi, name)
    for name in r.__all__:
        assert hasattr(r, name)
        assert hasattr(mi, name)
